function add(label,list,records){for(const row of records){const found=list.find(x=>x.id===row.id);if(found){if(JSON.stringify(found)!==JSON.stringify(row))throw Error('Expansion ID collision in '+label+': '+row.id);}else list.push(row);}}
for(const row of data.subPaths){const parent=JD.CULT.paths[row.path];if(!parent)throw Error('Missing expansion parent path: '+row.path);add('subpaths',parent.subPaths,[row]);}
add('materials',JD.ITEMS.materials,data.materials);
add('recipes',JD.ITEMS.recipes,data.recipes);
add('techniques',JD.TECH.techniques,data.techniques);
add('beasts',JD.BEASTS.species,data.beasts);
if(JD.EXPANSION&&JSON.stringify(JD.EXPANSION)!==JSON.stringify(data))throw Error('Conflicting JD.EXPANSION definition');
JD.EXPANSION=JD.EXPANSION||data;
